    test('returns true when point is just before end', () => {
      const start = new Date('2024-01-01T00:00:00Z');
      const end = new Date('2024-01-02T00:00:00Z');
      const interval = createInterval(start, end);

      const point = new Date('2024-01-01T23:59:59.999Z');
      expect(isPointInRange(point, interval)).toBe(true);
    });

    test('returns false when point is at end', () => {
      const start = new Date('2024-01-01T00:00:00Z');
      const end = new Date('2024-01-02T00:00:00Z');
      const interval = createInterval(start, end);

      const point = new Date('2024-01-02T00:00:00Z');
      expect(isPointInRange(point, interval)).toBe(false);
    });

    test('returns false when point is after end', () => {
      const start = new Date('2024-01-01T00:00:00Z');
      const end = new Date('2024-01-02T00:00:00Z');
      const interval = createInterval(start, end);

      const point = new Date('2024-01-02T00:00:01Z');
      expect(isPointInRange(point, interval)).toBe(false);
    });

    test('returns true for open end interval', () => {
      const start = new Date('2024-01-01T00:00:00Z');
      const interval = createOpenEndInterval(start);

      const point = new Date('2024-01-03T00:00:00Z');
      expect(isPointInRange(point, interval)).toBe(true);
    });

    test('returns false for open start interval', () => {
      const end = new Date('2024-01-02T00:00:00Z');
