    test('returns true when intervals fully overlap', () => {
      const a = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-03T00:00:00Z'));
      const b = createInterval(new Date('2024-01-02T00:00:00Z'), new Date('2024-01-04T00:00:00Z'));

      expect(intervalsOverlap(a, b)).toBe(true);
    });

    test('returns false when intervals are separate', () => {
      const a = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));
      const b = createInterval(new Date('2024-01-03T00:00:00Z'), new Date('2024-01-04T00:00:00Z'));

      expect(intervalsOverlap(a, b)).toBe(false);
