      const b = createInterval(new Date('2024-01-02T00:00:00Z'), new Date('2024-02-02T00:00:00Z'));
      // When b starts exactly at a's end (only if b.end === a.end)
      // Actually by interval math, if b.end > a.end, they overlap slightly
    });

    test('returns false when one interval is fully inside another', () => {
      const a = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-03T00:00:00Z'));
      const b = createInterval(new Date('2024-01-02T00:00:00Z'), new Date('2024-01-03T00:00:00Z'));

      expect(intervalsOverlap(a, b)).toBe(true);
    });
  });

  describe('containsInterval', () => {
