    test('returns false when inner interval touches outer at start', () => {
      const outer = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-06T00:00:00Z'));
      const inner = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-04T00:00:00Z'));

      expect(containsInterval(outer, inner)).toBe(true);
    });

    test('returns false when inner interval touches outer at end', () => {
      const outer = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-06T00:00:00Z'));
      const inner = createInterval(new Date('2024-01-02T00:00:00Z'), new Date('2024-01-06T00:00:00Z'));

      expect(containsInterval(outer, inner)).toBe(true);
    });

    test('returns false when inner interval is not fully contained', () => {
      const outer = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-06T00:00:00Z'));
      const inner = createInterval(new Date('2024-01-04T00:00:00Z'), new Date('2024-01-07T00:00:00Z'));

      // inner.end is outside outer.end → false
