      const interval = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));
      expect(isIntervalOpenEnded(interval)).toBe(false);
    });

    test('returns true for open-ended interval', () => {
      const interval = createOpenEndInterval(new Date('2024-01-01T00:00:00Z'));
      expect(isIntervalOpenEnded(interval)).toBe(true);
    });
  });

  describe('intervalKey', () => {
    test('returns consistent string for equal intervals', () => {
      const interval1 = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));
      const interval2 = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));

      expect(intervalKey(interval1)).toBe(intervalKey(interval2));
