      const interval2 = createInterval(new Date('2024-01-02T00:00:00Z'), new Date('2024-01-03T00:00:00Z'));

      expect(intervalKey(interval1)).not.toBe(intervalKey(interval2));
    });
  });

  describe('parseInterval', () => {
    test('parses valid RFC 3339 interval string', () => {
      const interval = parseInterval('2024-01-01T00:00:00Z/2024-01-02T00:00:00Z');
      expect(interval).toBeTruthy();
      expect(interval.start).toEqual(new Date('2024-01-01T00:00:00Z'));
      expect(interval.end).toEqual(new Date('2024-01-02T00:00:00Z'));
    });

    test('returns null for invalid format', () => {
      expect(parseInterval('invalid')).toBeNull();
      expect(parseInterval('2024-01-01/2024-01-02')).toBeNull();
    });
  });

  describe('formatInterval', () => {
    test('formats interval as RFC 3339 string', () => {
      const interval = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));
      const formatted = formatInterval(interval);

      expect(formatted).toBe('2024-01-01T00:00:00Z/2024-01-02T00:00:00Z');
    });

    test('throws for open-ended interval', () => {
      const interval = createOpenEndInterval(new Date('2024-01-01T00:00:00Z'));
      assert.throws(() => formatInterval(interval), Error);
    });
  });

  describe('cloneInterval', () => {
    test('returns independent copy', () => {
      const original = createInterval(new Date('2024-01-01T00:00:00Z'), new Date('2024-01-02T00:00:00Z'));
      const cloned = cloneInterval(original);

      // Should be equal
      expect(cloned.start).toEqual(original.start);
      expect(cloned.end).toEqual(original.end);

      // But not same object
      expect(cloned.end).not.toBe(original.end);
    });
  });

  describe('fromConstraint', () => {
    test('creates interval from constraints', () => {
      const start = Date.now();
      const end = start + 86400000;

      const interval = fromConstraint(start, end);
      expect(interval.start.getTime()).toBe(start);
      expect(interval.end.getTime()).toBe(end);
    });
  });

  describe('DEFAULT_CANCEL_GRACE_PERIOD_MS', () => {
    test('is 48 hours in milliseconds', () => {
      expect(DEFAULT_CANCEL_GRACE_PERIOD_MS).toBe(48 * 60 * 60 * 1000);
    });
  });
});

