      expect(canceled).toBe(true);
      expect(reservation.canceledAt).toBeDefined();
      expect(reservation.cancelReason).toBe('User requested cancellation');
    });

    test('does not allow cancellation after grace period', () => {
      const calendar = new Calendar();

      const reservation = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_abc',
        requestedAt: new Date(Date.now() - 65 * 60 * 60 * 1000), // 65 hours ago (past grace period)
      });

      const canceled = calendar.cancelReservation(reservation.id, 'User requested cancellation');

      expect(canceled).toBe(false);
      expect(reservation.canceledAt).toBeUndefined();
    });

    test('returns false for non-existent reservation', () => {
      const calendar = new Calendar();
      const canceled = calendar.cancelReservation('res_nonexistent', 'Reason');

      expect(canceled).toBe(false);
    });
  });

  describe('Reservation Queries', () => {
    test('finds reservation by ID', () => {
      const calendar = new Calendar();

      const reservation = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_abc',
        requestedAt: new Date(),
      });

      const found = calendar.findReservation(reservation.id);
      expect(found).toBeTruthy();
      expect(found.id).toBe(reservation.id);
    });

    test('returns null for non-existent reservation', () => {
      const calendar = new Calendar();
      const found = calendar.findReservation('res_nonexistent');

      expect(found).toBeNull();
    });

    test('gets reservations by equipment ID', () => {
      const calendar = new Calendar();

      const reservation1 = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_abc',
        requestedAt: new Date(),
      });

      const reservation2 = calendar.createReservation({
        equipmentId: 'eq_test456',
        borrowerId: 'user_xyz',
        requestedAt: new Date(),
      });

      const eq1Reservations = calendar.getReservationsByEquipment('eq_test123');
      expect(eq1Reservations).toHaveLength(1);
      expect(eq1Reservations[0].id).toBe(reservation1.id);

      const eq2Reservations = calendar.getReservationsByEquipment('eq_test456');
      expect(eq2Reservations).toHaveLength(1);
      expect(eq2Reservations[0].id).toBe(reservation2.id);
    });

    test('gets reservations by borrower ID', () => {
      const calendar = new Calendar();

      const reservation1 = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_test1',
        requestedAt: new Date(),
      });

      const reservation2 = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_test1',
        requestedAt: new Date(),
      });

      const userReservations = calendar.getReservationsByBorrower('user_test1');
      expect(userReservations).toHaveLength(2);
      expect(userReservations[0].id).toBe(reservation1.id);
      expect(userReservations[1].id).toBe(reservation2.id);
    });

    test('gets active reservations (excluding canceled)', () => {
      const calendar = new Calendar();

      const reservation1 = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_test1',
        requestedAt: new Date(Date.now() - 50 * 60 * 60 * 1000),
      });

      calendar.cancelReservation(reservation1.id, 'Cancelled outside grace period');

      const reservation2 = calendar.createReservation({
        equipmentId: 'eq_test456',
        borrowerId: 'user_test1',
        requestedAt: new Date(Date.now() - 10 * 60 * 60 * 1000),
      });

      const active = calendar.getActiveReservations();
      expect(active).toHaveLength(1);
      expect(active[0].id).toBe(reservation2.id);
    });
  });

  describe('Multiple Equipment Support', () => {
    test('manages reservations for multiple equipment', () => {
      const calendar = new Calendar();

      const eq1Reservation = calendar.createReservation({
        equipmentId: 'eq_drill_1',
        borrowerId: 'user_abc',
        requestedAt: new Date(),
      });

      const eq2Reservation = calendar.createReservation({
        equipmentId: 'eq_mill_2',
        borrowerId: 'user_xyz',
        requestedAt: new Date(),
      });

      const eq1Reservations = calendar.getReservationsByEquipment('eq_drill_1');
      const eq2Reservations = calendar.getReservationsByEquipment('eq_mill_2');

      expect(eq1Reservations).toHaveLength(1);
      expect(eq2Reservations).toHaveLength(1);
      expect(eq1Reservations[0].id).toBe(eq1Reservation.id);
      expect(eq2Reservations[0].id).toBe(eq2Reservation.id);
    });

    test('maintains separate reservation state for different equipment', () => {
      const calendar = new Calendar();

      const nowMs = Date.now();

      const res1 = calendar.createReservation({
        equipmentId: 'eq_1',
        borrowerId: 'user_1',
        requestedAt: new Date(nowMs),
      });

      const res2 = calendar.createReservation({
        equipmentId: 'eq_1',
        borrowerId: 'user_2',
        requestedAt: new Date(nowMs),
      });

      // Cancel only first reservation
      calendar.cancelReservation(res1.id, 'User 1');

      const eq1Reservations = calendar.getReservationsByEquipment('eq_1');
      expect(eq1Reservations).toHaveLength(1);
      expect(eq1Reservations[0].id).toBe(res2.id);
      expect(eq1Reservations[0].canceledAt).toBeUndefined();
    });
  });

  describe('Edge Cases', () => {
    test('handles multiple reservations at same timestamp', () => {
      const calendar = new Calendar();

      const nowMs = Date.now();

      const res1 = calendar.createReservation({
        equipmentId: 'eq_1',
        borrowerId: 'user_1',
        requestedAt: new Date(nowMs),
      });

      const res2 = calendar.createReservation({
        equipmentId: 'eq_1',
        borrowerId: 'user_2',
        requestedAt: new Date(nowMs),
      });

      // Should not throw, will automatically schedule second ahead
      expect(res1.id).not.toBe(res2.id);
    });
  });

  describe('Reservation Indexing', () => {
    test('maintains index structure for fast querying', () => {
      const calendar = new Calendar();

      const nowMs = Date.now();

      calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_test1',
        requestedAt: new Date(nowMs),
      });

      expect(calendar.reservationIndex.size).toBeGreaterThan(0);
      expect(calendar.reservationIndex.has('res_' + nowMs.toString(36))).toBeTruthy();
    });
  });

  describe('Borrower Reservation Tracking', () => {
    test('tracks borrower-equipment association for existing bookings', () => {
      const calendar = new Calendar();

      const initTimeStr = Date.now().toString();

      const res1 = calendar.createReservation({
        equipmentId: 'eq_test123',
        borrowerId: 'user_abc',
        requestedAt: new Date(),
      });

      expect(calendar.borrowerReservedMap.has('eq_test123')).toBe(true);
      expect(calendar.borrowerReservedMap.get('eq_test123')).toBe(res1.id);
    });
  });
});

