      const reservation = {
        requestedAt: new Date(now - 35 * 60 * 60 * 1000),
        canceledAt: undefined,
      };

      const result = validateCancellation(reservation, new Date(cancellationDeadline));

      expect(result.cancellable).toBe(true);
      expect(result.timeRemainingMs).toBeLessThanOrEqual(DEFAULT_CANCEL_GRACE_PERIOD_MS);
    });

    test('rejects cancellation past grace period', () => {
      const now = new Date().getTime();
      const cancellationDeadline = new Date(now - 40 * 60 * 60 * 1000).getTime(); // 40 hours ago

      const reservation = {
        requestedAt: new Date(now - 65 * 60 * 60 * 1000),
        canceledAt: undefined,
      };

      const result = validateCancellation(reservation, new Date(cancellationDeadline));

