      // Short duration reservation with auto-renew enabled
      const result = createValidatedReservation({
        equipmentId: 'eq_test',
        borrowerId: 'user_abc',
        requestedAt: new Date(Date.now()),
        autoRenew: true,
      }, equipment, []);

      expect(result.validation.valid).toBe(false);
    });
  });

  describe('Conflicting interval start', () => {
    test('cannot start inside another reservation', () => {
      const nr = {
        pendingAt: new Date(Date.now() - 1200000), // 20 minutes ago
        interval: { start: new Date(Date.now() - 2000000), end: new Date(Date.now() + 1800000) },
        equipmentId: 'eq_test123',
        borrowerId: 'user_abc',
      };

      const equipment = {
        id: 'eq_test123',
        name: 'Tool',
        category: 'tools',
        status: 'available',
        maintenance: { state: 'ok' },
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      const opts = {
        equipmentId: 'eq_test123',
        borrowerId: 'user_xyz',
        requestedAt: new Date(Date.now()),
      };

      // NOW is 30 min after pendingAt, inside the interval and after start
      // Using an explicitly calculated startForReservation
      const reservationStartMs = 30 * 60 * 1000; // 30 minutes past request
      const intervalStartForNew = new Date(Date.now() + reservationStartMs);
      const intervalEndForReservation = new Date(Date.now() + reservationStartMs + 7200000); // 2 hour plus padding

      const currentViewStart = new Date();
      const currentViewEnd = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

      const existingIntervals = [createInterval(nr.interval.start, nr.interval.end)];
      const newInterval = createInterval(intervalStartForNew, intervalEndForReservation);
      const canStart = existingIntervals.every(int => !isPointInRange(intervalStartForNew, createInterval(int.start, int.end)));

      expect(canStart).toBe(false);
    });
  });
});

