describe('Storage Module', () => {
  describe('InMemoryStorage', () => {
    test('initializes with empty catalog', async () => {
      const storage = new InMemoryStorage();
      const catalog = await storage.load();

      expect(catalog).toBeTruthy();
      expect(catalog.equipment).toHaveLength(0);
      expect(catalog.categories).toHaveLength(0);
    });

    test('loads previously stored catalog', async () => {
      const storage = new InMemoryStorage();

      const categories = [
        { id: 'cat1', name: 'Tools' },
        { id: 'cat2', name: 'Materials' },
      ];

      const equipment = [
        {
          id: 'eq1',
          name: 'Power Drill',
          category: 'cat1',
          status: 'available',
          maintenance: { state: 'ok' },
          createdAt: new Date(),
          updatedAt: new Date(),
        },
      ];

      const expectedCatalog = {
        categories,
        equipment,
        updatedAt: new Date(),
      };

      await storage.save(expectedCatalog);
      const loadedCatalog = await storage.load();

      expect(loadedCatalog).toEqual(expectedCatalog);
    });

    test('deep clones catalog on load', async () => {
      const storage = new InMemoryStorage();

      const categories = [{ id: 'cat1', name: 'Tools' }];
      const equipment = [{
        id: 'eq1',
        name: 'Power Drill',
        category: 'cat1',
        status: 'available',
        maintenance: { state: 'ok' },
        createdAt: new Date(),
        updatedAt: new Date(),
      }];

      const catalog = {
        categories,
        equipment,
        updatedAt: new Date(),
      };

      await storage.save(catalog);
      const loadedCatalog = await storage.load();

      // Verify they're not the same object
      expect(loadedCatalog).toBe(storage.catalog);
      expect(loadedCatalog).toEqual(catalog);
    });
  });

  describe('FileStorage', () => {
    let tmpDir;
    let catalogPath;
    let snapshotPath;

    test('should save catalog to file', async () => {
      tmpDir = tempfile();
      catalogPath = `${tmpDir}/catalog.json`;

      const categories = [{ id: 'cat1', name: 'Tools' }];
      const equipment = [{
        id: 'eq1',
        name: 'Power Drill',
        category: 'cat1',
        status: 'available',
        maintenance: { state: 'ok' },
        createdAt: new Date(),
        updatedAt: new Date(),
      }];

      const expectedCatalog = {
        categories,
        equipment,
        updatedAt: new Date(),
      };

      const storage = new FileStorage(catalogPath);

      await storage.save(expectedCatalog);

      // Read file and verify content
      const fs = await import('node:fs/promises');
      const content = await fs.readFile(catalogPath, 'utf-8');
      expect(content).toContain('"categories"');
    });

    test('should load catalog from file', async () => {
      tmpDir = tempfile();
      catalogPath = `${tmpDir}/catalog.json`;

      const categories = [{ id: 'cat1', name: 'Tools' }];
      const equipment = [{
        id: 'eq1',
        name: 'Power Drill',
        category: 'cat1',
        status: 'available',
        maintenance: { state: 'ok' },
        createdAt: new Date(),
        updatedAt: new Date(),
      }];

      const expectedCatalog = {
        categories,
        equipment,
        updatedAt: new Date(),
      };

      const storage = new FileStorage(catalogPath);
      await storage.save(expectedCatalog);

      const loadedCatalog = await storage.load();

      expect(loadedCatalog).toEqual(expectedCatalog);
    });

    test('handles nonexistent catalog file gracefully', async () => {
      tmpDir = tempfile();
      catalogPath = `${tmpDir}/nonexistent.json`;

      const fs = await import('node:fs/promises');
      await fs.rm(tmpDir, { recursive: true, force: true });

      const storage = new FileStorage(catalogPath);
      const catalog = await storage.load();

      expect(catalog).toBeNull();
    });
  });
});

async function tempfile() {
  const fs = await import('node:fs/promises');
  const { tmpdir } = await import('node:os');
  const { randomBytes } = await import('node:crypto');

  const id = randomBytes(8).toString('hex');
  const dir = `${tmpdir()}/lantern-test-${id}`;

  await fs.mkdir(dir, { recursive: true });
  return dir;
}

