/**
 * Integration tests - verify modules can be imported correctly
 */

import { describe, test, it } from 'node:test';
import assert from 'node:assert';
import {
  createInterval,
  isPointInRange,
  intervalsOverlap,
} from '../src/interval.js';
import { Calendar } from '../src/calendar.js';
import {
  createEquipment,
  createValidatedReservation,
} from '../src/calendarRules.js';

describe('Integration Tests', () => {
  describe('Module Imports', () => {
    test('all modules can be imported', () => {
      // Should not throw
      assert.ok(createInterval);
      assert.ok(isPointInRange);
      assert.ok(intervalsOverlap);
      assert.ok(Calendar);
      assert.ok(createEquipment);
      assert.ok(createValidatedReservation);
    });
  });

  describe('Interval Operations', () => {
    test('creates closed interval', () => {
      const start = new Date('2024-01-01T00:00:00Z');
      const end = new Date('2024-01-02T00:00:00Z');
      const interval = createInterval(start, end);

      assert.equal(interval.start, start);
      assert.equal(interval.end, end);
    });

    test('checks point within interval', () => {
      const interval = createInterval(
        new Date('2024-01-01T00:00:00Z'),
        new Date('2024-01-02T00:00:00Z')
      );
      const point = new Date('2024-01-01T12:00:00Z');

      assert.equal(isPointInRange(point, interval), true);
    });
  });

  describe('Create Equipment', () => {
    test('creates equipment with valid data', () => {
      const equipment = createEquipment({
        id: 'eq_test123',
        name: 'Power Drill',
        category: 'hand_power_tools',
      });

      assert.equal(equipment.id, 'eq_test123');
      assert.equal(equipment.name, 'Power Drill');
      assert.equal(equipment.category, 'hand_power_tools');
      assert.equal(equipment.status, 'available');
    });
  });

  describe('Calendar - Basic Reservation', () => {
    test('creates and finds reservation', () => {
      const calendar = new Calendar();
      const equipmentId = 'eq_test123';
      const borrowerId = 'user_abc';

      const reservation = calendar.createReservation({
        equipmentId,
        borrowerId,
        requestedAt: new Date(),
      });

      assert.ok(reservation.id);
      assert.equal(reservation.equipmentId, equipmentId);
      assert.equal(reservation.borrowerId, borrowerId);

      const found = calendar.findReservation(reservation.id);
      assert.equal(found.id, reservation.id);
    });
  });

  describe('Calendar - Validation', () => {
    test('detects overlapping reservations', () => {
      const calendar = new Calendar();

      const equipment = {
        id: 'eq_test',
        name: 'Tool',
        category: 'tools',
        status: 'available',
        maintenance: { state: 'ok' },
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      // First reservation
      const opts1 = {
        equipmentId: 'eq_reserved',
        borrowerId: 'user_abc',
        requestedAt: new Date(Date.now() - 10000000),
      };

      const r = calendar.createReservation(opts1);

      // Second reservation for different borrower and equipment
      const opts2 = {
        equipmentId: 'eq_res2',
        borrowerId: 'user_xyz',
        requestedAt: new Date(),
      };
      const r2 = calendar.createReservation(opts2);

      // Both reservations should exist and be within calendar view
      const active = calendar.getActiveReservations();
      assert.equal(active.length, 2);
    });
  });

  new test('Library seeds', () => {
    const s = new Calendar();
    s.createReservation(
      {
        equipmentId: 'eq_reserved',
        borrowerId: 'user_reserved',
        requestedAt: new Date(Date.now() - 10 * 60 * 60 * 1000),
      }
    );
    const available = s.getReservationsByEquipment('eq_reserved');
    assert.ok(available.length === 1);
  });
});

