/**
 * Lantern Ledger - Demo showing basic usage
 */

import { Calendar } from './src/calendar.js';
import { createEquipment, createValidatedReservation } from './src/calendarRules.js';
import { createInterval } from './src/interval.js';

console.log('=== Lantern Ledger Demo ===\n');

// Create a calendar instance
const calendar = new Calendar();

// Create equipment
console.log('1. Creating equipment:');
const drill = createEquipment({
  id: 'eq_drill_001',
  name: 'Cordless Drill',
  category: 'power_tools',
  serialNumber: 'SN-DR0012345',
});

console.log(`   - ${drill.name} (${drill.id})`);
console.log(`   - Status: ${drill.status}`);
console.log(`   - Serial: ${drill.serialNumber}\n`);

// Create another equipment
const welder = createEquipment({
  id: 'eq_welder_002',
  name: 'Welding Station',
  category: 'crafting',
  serialNumber: 'SN-WEL9876543',
});

console.log('2. Creating equipment:');
console.log(`   - ${welder.name} (${welder.id})`);
console.log(`   - Status: ${welder.status}`);
console.log(`   - Serial: ${welder.serialNumber}\n`);

// Create a reservation
console.log('3. Creating reservation:');
const reservation = calendar.createReservation({
  equipmentId: 'eq_drill_001',
  borrowerId: 'user_john_doe',
  requestedAt: new Date(),
  autoRenew: false,
});

console.log(`   - Reservation ID: ${reservation.id}`);
console.log(`   - Equipment: ${reservation.equipmentId}`);
console.log(`   - Borrower: ${reservation.borrowerId}`);
console.log(`   - Requested at: ${reservation.requestedAt.toISOString()}`);
console.log(`   - Interval: ${reservation.interval.start.toISOString()} to ${reservation.interval.end.toISOString()}\n`);

// Check status of equipment
console.log('4. Equipment status after reservation:');
console.log(`   - ${drill.name}: ${drill.status}`);
console.log(`   - Auto-renew enabled: ${drill.autoRenew ? 'Yes' : 'No'}\n`);

// Create another reservation for different equipment
console.log('5. Creating another reservation:');
const reservation2 = calendar.createReservation({
  equipmentId: 'eq_welder_002',
  borrowerId: 'user_jane_smith',
  requestedAt: new Date(),
  autoRenew: false,
});

console.log(`   - Reservation ID: ${reservation2.id}`);
console.log(`   - Equipment: ${reservation2.equipmentId}`);
console.log(`   - Borrower: ${reservation2.borrowerId}\n`);

// Query reservations
console.log('6. Querying reservations:');
const borrowerReservations = calendar.getReservationsByBorrower('user_john_doe');
const equipmentReservations = calendar.getReservationsByEquipment('eq_drill_001');
const activeReservations = calendar.getActiveReservations();

console.log(`   - John Doe's reservations: ${borrowerReservations.length}`);
console.log(`   - Drill reservations: ${equipmentReservations.length}`);
console.log(`   - Active reservations: ${activeReservations.length}\n`);

// Create an interval example
console.log('7. Interval operations:');
const now = new Date();
const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
const interval = createInterval(now, tomorrow);
console.log(`   - Created interval from ${interval.start.toISOString()} to ${interval.end.toISOString()}`);
console.log(`   - Duration: ${(interval.end.getTime() - interval.start.getTime()) / (1000 * 60 * 60)} hours\n`);

// Feature validation
console.log('8. Feature validation:');
const validation = createValidatedReservation(
  {
    equipmentId: 'eq_drill_001',
    borrowerId: 'user_john_doe',
    requestedAt: new Date(),
    autoRenew: false,
  },
  drill,
  calendar.getActiveReservations()
);

console.log(`   - Can reserve equipment: ${validation.validation.valid ? 'Yes ✓' : 'No ✗'}`);
console.log('=== Demo Complete ===');

