/**
 * Reservation State Machine
 * 
 * Main states: draft, confirmed, checked-out, returned, cancelled, expired
 * Each state has valid transitions to next states
 * 
 * State definitions:
 * - draft: Initial state for request (no equipment booking yet)
 * - confirmed: Confirmed and ready for checkout
 * - checked-out: Equipment check-out initiated
 * - returned: Equipment checkout completed
 * - cancelled: Reservation cancelled (by either party)
 * - expired: Reservation deadline passed, no checkout occurred
 */

import { createInterval } from './interval.js';

/**
 * @typedef {Object} Reservation
 * @property {string} id
 * @property {string} equipmentId
 * @property {string} borrowerId
 * @property {import('./interval.js').Interval} interval
 * @property {'draft' | 'confirmed' | 'checked-out' | 'returned' | 'cancelled' | 'expired'} status
 * @property {boolean} autoRenew
 * @property {Date} requestedAt
 * @property {Date} [confirmedAt]
 * @property {Date} [checkoutStartedAt]
 * @property {Date} [checkoutCompletedAt]
 * @property {Date} [returnedAt]
 * @property {Date} [canceledAt]
 * @property {string} [cancelReason]
 * @property {Date} [expiresAt]
 */

/**
 * @typedef {Object} Equipment
 * @property {string} id
 * @property {string} name
 * @property {string} category
 * @property {string} [serialNumber]
 * @property {'available' | 'maintenance' | 'in_use' | 'reserved' | 'auto_reserved'} status
 * @property {EquipmentMaintenance} maintenance
 * @property {Date} createdAt
 * @property {Date} updatedAt
 */

/**
 * @typedef {Object} EquipmentMaintenance
 * @property {'ok' | 'in_progress' | 'pending' | 'completed'} state
 * @property {Date} [dueDate]
 * @property {string} [notes]
 */

/**
 * State machine configuration
 * @typedef {Object} StateMachineOptions
 * @property {number} [cancelGracePeriodMs=48 * 60 * 60 * 1000]
 * @property {import('./interval').Interval} [currentInterval]
 */

/**
 * Default cancellation grace period: 48 hours
 */
export const DEFAULT_CANCEL_GRACE_PERIOD_MS = 48 * 60 * 60 * 1000;

/**
 * Reservation state - canonical forms
 */
export const ReservationState = {
  DRAFT: 'draft',
  CONFIRMED: 'confirmed',
  'CHECKED-OUT': 'checked-out',
  RETURNED: 'returned',
  CANCELLED: 'cancelled',
  EXPIRED: 'expired',
};

/**
 * Valid state transitions
 * Key: current state, Value: array of valid next states
 */
const stateTransitions = {
  [ReservationState.DRAFT]: [ReservationState.CONFIRMED, ReservationState.CANCELLED],
  [ReservationState.CONFIRMED]: [ReservationState.CHECKED-OUT, ReservationState.CANCELLED, ReservationState.EXPIRED],
  [ReservationState['CHECKED-OUT']]: [ReservationState.RETURNED, ReservationState.CANCELLED],
  [ReservationState.RETURNED]: [],
  [ReservationState.CANCELLED]: [],
  [ReservationState.EXPIRED]: [],
};

/**
 * Get valid transitions for a state
 * 
 * @param {string} state
 * @returns {string[]}
 */
export function getValidTransitions(state) {
  return stateTransitions[state] || [];
}

/**
 * Check if a transition is valid
 * 
 * @param {string} fromState
 * @param {string} toState
 * @returns {boolean}
 */
export function isValidTransition(fromState, toState) {
  return getValidTransitions(fromState).includes(toState);
}

/**
 * Check if a transition is allowed by a rule function
 * 
 * @param {string} fromState
 * @param {string} toState
 * @param {Function} ruleFn
 * @returns {boolean}
 */
export function isTransitionAllowed(fromState, toState, ruleFn) {
  if (!isValidTransition(fromState, toState)) {
    return false;
  }
  const result = ruleFn(fromState, toState);
  return result.allowed !== false;
}

/**
 * Reserve - Create and confirm a reservation
 * Transitions: draft → confirmed
 * 
 * This is the initial state machine entry point
 * 
 * @param {Object} opts
 * @param {string} opts.equipmentId
 * @param {string} opts.borrowerId
 * @param {Date} opts.requestedAt
 * @param {import('./interval.js').Interval} opts.interval
 * @param {boolean} [opts.autoRenew]
 * @param {Date} [opts.expiresAt]
 * @returns {Reservation}
 */
export function createReservation(opts) {
  const {
    equipmentId,
    borrowerId,
    requestedAt,
    interval,
    autoRenew = false,
    expiresAt,
  } = opts;

  if (!interval.start || !interval.end) {
    throw new Error('Interval must have both start and end dates');
  }

  const now = new Date(requestedAt);

  return {
    id: generateId(),
    equipmentId,
    borrowerId,
    interval,
    status: ReservationState.DRAFT,
    autoRenew,
    requestedAt: now,
    expiresAt: expiresAt || new Date(now.getTime() + 86400000),
  };
}

/**
 * Confirm reservation
 * Transitions: draft → confirmed
 * 
 * Rules:
 * - Request time must be in the past
 * - Interval must be in the future (relative to requestedAt)
 * - Equipment must be available
 * - No overlapping reservations for borrower or equipment
 * 
 * @param {Reservation} reservation
 * @param {Equipment} equipment
 * @param {Reservation[]} existingReservations
 * @param {Function} checkAvailability - Function to check equipment availability
 * @returns {{allowed: boolean, reason?: string, updated?: Reservation}}
 */
export function confirmReservation(reservation, equipment, existingReservations, checkAvailability) {
  const currentInterval = createInterval(new Date(), new Date(Date.now() + 7 * 24 * 60 * 60 * 1000));

  // Rule 1: Request time must be in the past
  if (reservation.requestedAt.getTime() > currentInterval.start.getTime()) {
    return {
      allowed: false,
      reason: 'Reservation requested at a future time',
    };
  }

  // Rule 2: Validate interval boundaries
  validateReservationInterval(reservation, existingReservations, currentInterval);

  // Rule 3: Equipment must be available
  const availability = checkAvailability ? checkAvailability(equipment, reservation) : equipment.status === 'available';
  if (!availability) {
    return {
      allowed: false,
      reason: 'Equipment is not available for reservation',
    };
  }

  // Rule 4: No overlapping reservations for borrower
  const borrowerOverlaps = existingReservations.some((r) => {
    if (r.borrowerId !== reservation.borrowerId || r.status === ReservationState.CANCELLED) {
      return false;
    }
    return intervalsOverlap(r.interval, reservation.interval);
  });

  if (borrowerOverlaps) {
    const overlappedIds = existingReservations
      .filter((r) => r.borrowerId === reservation.borrowerId && r.status !== ReservationState.CANCELLED)
      .map((r) => r.id);

    return {
      allowed: false,
      reason: `Borrower has overlapping reservation(s): ${overlappedIds.join(', ')}`,
    };
  }

  // Rule 5: No overlapping reservations for equipment
  const equipmentOverlaps = existingReservations.some((r) => {
    if (r.equipmentId !== reservation.equipmentId || r.status === ReservationState.CANCELLED) {
      return false;
    }
    return intervalsOverlap(r.interval, reservation.interval);
  });

  if (equipmentOverlaps) {
    const overlappedIds = existingReservations
      .filter((r) => r.equipmentId === reservation.equipmentId && r.status !== ReservationState.CANCELLED)
      .map((r) => r.id);

    return {
      allowed: false,
      reason: `Equipment has overlapping reservation(s): ${overlappedIds.join(', ')}`,
    };
  }

  // All checks passed
  const updated = {
    ...reservation,
    status: ReservationState.CONFIRMED,
    confirmedAt: new Date(),
    requestedAt: new Date(reservation.requestedAt), // Ensure UTC
    interval: cloneInterval(reservation.interval),
  };

  return {
    allowed: true,
    updated,
  };
}

/**
 * Validate reservation interval
 * 
 * @param {Reservation} reservation
 * @param {Reservation[]} existingReservations
 * @param {import('./interval.js').Interval} currentInterval
 * @returns {{valid: boolean, reason?: string}}
 */
function validateReservationInterval(reservation, existingReservations, currentInterval) {
  // Start time must be in the past relative to currentInterval
  if (reservation.interval.start.getTime() < currentInterval.start.getTime()) {
    return {
      valid: false,
      reason: 'Reservation start time is before current interval start',
    };
  }

  // End time must be in the future relative to currentInterval
  if (reservation.interval.end.getTime() < currentInterval.start.getTime()) {
    return {
      valid: false,
      reason: 'Reservation end time is before current interval start',
    };
  }

  // End time must be after start time
  if (reservation.interval.end.getTime() <= reservation.interval.start.getTime()) {
    return {
      valid: false,
      reason: 'Reservation end time must be after start time',
    };
  }

  // Check for overlap with any existing reservation
  const hasOverlap = existingReservations.some((r) => {
    if (r.status === ReservationState.CANCELLED) {
      return false;
    }
    return intervalsOverlap(r.interval, reservation.interval);
  });

  if (hasOverlap) {
    return {
      valid: false,
      reason: 'Reservation overlaps with existing reservation',
    };
  }

  return { valid: true };
}

/**
 * Checkout equipment
 * Transitions: confirmed → checked-out
 * 
 * Rules:
 * - Reservation must be in confirmed state
 * - Must be within 30 minutes of confirmed time (buffer)
 * - Equipment must be available (not in maintenance or already checked out)
 * - No overlapping concurrent checkouts for borrower
 * - Equipment status must change to 'in_use'
 * 
 * @param {Reservation} reservation
 * @param {Equipment} equipment
 * @param {Function} getEquipmentStatus - Function to get current equipment status
 * @returns {{allowed: boolean, reason?: string}}
 */
export function checkoutReservation(reservation, equipment, getEquipmentStatus) {
  // Rule 1: Must be in confirmed state
  if (reservation.status !== ReservationState.CONFIRMED) {
    return {
      allowed: false,
      reason: `Cannot checkout from state: ${reservation.status}`,
    };
  }

  // Rule 2: Equipment must be available
  const status = getEquipmentStatus ? getEquipmentStatus(equipment) : equipment.status;
  if (status !== 'available' && status !== 'reserved') {
    return {
      allowed: false,
      reason: `Equipment is not available: ${status}`,
    };
  }

  // Rule 3: Must be within 30 minutes of confirmed time
  if (reservation.confirmedAt) {
    const checkoutTime = new Date();
    const confirmedTime = reservation.confirmedAt.getTime();
    const bufferMs = 30 * 60 * 1000; // 30 minutes

    if (checkoutTime.getTime() - confirmedTime > bufferMs) {
      return {
        allowed: false,
        reason: 'Reservation checkout time exceeded 30-minute buffer',
      };
    }
  }

  // All checks passed
  return {
    allowed: true,
  };
}

/**
 * Complete checkout (finalize the checkout)
 * Transitions: confirmed → checked-out
 * 
 * This is separate from checkout to allow equipment state transition
 * 
 * Rules:
 * - Must be in confirmed state
 * - Can only be called once (check guards)
 * 
 * @param {Reservation} reservation
 * @param {Equipment} equipment
 * @param {Function} getEquipmentStatus - Function to get current equipment status
 * @returns {{allowed: boolean, reason?: string, updated?: Equipment}}
 */
export function completeCheckout(reservation, equipment, getEquipmentStatus) {
  const status = getEquipmentStatus ? getEquipmentStatus(equipment) : equipment.status;

  // Rule 1: Must be in confirmed state
  if (reservation.status !== ReservationState.CONFIRMED) {
    return {
      allowed: false,
      reason: `Cannot complete checkout from state: ${reservation.status}`,
    };
  }

  // Rule 2: Equipment must be in available status when creating the booking
  if (status !== 'available' && status !== 'reserved') {
    return {
      allowed: false,
      reason: `Equipment is not available: ${status}`,
    };
  }

  // Rule 3: Cannot complete checkout more than once
  if (reservation.checkoutStartedAt) {
    return {
      allowed: false,
      reason: 'Checkout already started',
    };
  }

  // All checks passed
  const updated = {
    ...equipment,
    status: 'in_use',
    maintanence: {
      ...equipment.maintenance,
      notes: equipment.maintenance.notes || 'Begun checkout process',
    },
  };

  return {
    allowed: true,
    updated,
  };
}

/**
 * Return equipment
 * Transitions: checked-out → returned
 * 
 * Rules:
 * - Must be in checked-out state
 * - Equipment status must indicate it's in use
 * - Can only be returned after checkout is initiated
 * 
 * @param {Reservation} reservation
 * @param {Equipment} equipment
 * @param {Function} getEquipmentStatus - Function to get current equipment status
 * @returns {{allowed: boolean, reason?: string}}
 */
export function returnReservation(reservation, equipment, getEquipmentStatus) {
  const status = getEquipmentStatus ? getEquipmentStatus(equipment) : equipment.status;

  // Rule 1: Must be in checked-out state
  if (reservation.status !== ReservationState['CHECKED-OUT']) {
    return {
      allowed: false,
      reason: `Cannot return from state: ${reservation.status}`,
    };
  }

  // Rule 2: If equipment status was 'in_use', verify return makes sense
  if (status === 'available' || status === 'maintenance') {
    // This is a true return - equipment was checked out
  } else if (status === 'in_use') {
    // Equipment is still in use, return blocked
    return {
      allowed: false,
      reason: 'Equipment is still in use',
    };
  } else {
    return {
      allowed: false,
      reason: `Invalid equipment status for return: ${status}`,
    };
  }

  // All checks passed
  return {
    allowed: true,
  };
}

/**
 * Finalize return
 * Transitions: checked-out → returned
 * 
 * This completes the return process and updates equipment status
 * 
 * Rules:
 * - Must be in checked-out state
 * - Has a matching checkout session
 * 
 * @param {Reservation} reservation
 * @param {Equipment} equipment
 * @param {Function} getEquipmentStatus - Function to get current equipment status
 * @returns {{allowed: boolean, reason?: string, updated?: Equipment}}
 */
export function finalizeReturn(reservation, equipment, getEquipmentStatus) {
  const status = getEquipmentStatus ? getEquipmentStatus(equipment) : equipment.status;

  // Rule 1: Must be in checked-out state
  if (reservation.status !== ReservationState['CHECKED-OUT']) {
    return {
      allowed: false,
      reason: `Cannot finalize return from state: ${reservation.status}`,
    };
  }

  // Rule 2: Must have an active checkout session
  if (!reservation.checkedoutStartedAt) {
    return {
      allowed: false,
      reason: 'No checkout session found',
    };
  }

  // All checks passed
  const updated = {
    ...equipment,
    status: 'available',
  };

  return {
    allowed: true,
    updated,
  };
}

/**
 * Cancel reservation
 * Transitions: draft, confirmed, checked-out → cancelled
 * 
 * Rules:
 * - Within grace period (48 hours from requestedAt)
 * - Or by equipment coordinator
 * 
 * @param {Reservation} reservation
 * @param {Date} [cancellationDeadline]
 * @param {string} [cancelReason]
 * @param {string} [cancelerId]
 * @returns {{allowed: boolean, reason?: string}}
 */
export function cancelReservation(reservation, cancellationDeadline, cancelReason, cancelerId) {
  const now = new Date();
  const cancellationDeadlineTime = cancellationDeadline ? cancellationDeadline.getTime() : Infinity;

  // Rule 1: Must be in a cancelable state
  const cancelableStates = [ReservationState.DRAFT, ReservationState.CONFIRMED, ReservationState['CHECKED-OUT']];
  if (!cancelableStates.includes(reservation.status)) {
    return {
      allowed: false,
      reason: `Cannot cancel from state: ${reservation.status}`,
    };
  }

  // Rule 2: Check cancellation authority
  if (now.getTime() > cancellationDeadlineTime) {
    // Outside grace period - only coordinator can cancel
    if (!cancelerId || cancelerId === reservation.borrowerId) {
      return {
        allowed: false,
        reason: 'Cannot cancel outside grace period: only equipment coordinator can cancel',
      };
    }
  }

  // All checks passed
  return {
    allowed: true,
  };
}

/**
 * Expire reservation
 * Transitions: confirmed → expired
 * 
 * Rules:
 * - Only expires from confirmed state
 * - After expiration, cannot be extended or checked out
 * 
 * @param {Reservation} reservation
 * @param {Date} expirationTime
 * @returns {{allowed: boolean, reason?: string, updated?: Reservation}}
 */
export function expireReservation(reservation, expirationTime) {
  // Rule 1: Must be in confirmed state
  if (reservation.status !== ReservationState.CONFIRMED) {
    return {
      allowed: false,
      reason: `Cannot expire from state: ${reservation.status}`,
    };
  }

  // Rule 2: Must be time to expire
  if (new Date(expirationTime).getTime() > new Date().getTime()) {
    return {
      allowed: false,
      reason: 'Reservation not yet expired',
    };
  }

  // Rule 3: Cannot expire already moved to checked-out
  if (reservation.status === ReservationState['CHECKED-OUT']) {
    return {
      allowed: false,
      reason: 'Cannot expire checked-out reservation',
    };
  }

  // All checks passed
  const updated = {
    ...reservation,
    status: ReservationState.EXPIRED,
    canceledAt: new Date(),
    cancelReason: 'Reservation expired',
  };

  return {
    allowed: true,
    updated,
  };
}

/**
 * Generate unique reservation ID
 */
function generateId() {
  return `res_${Date.now().toString(36)}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Helper: Get reservation state by status string normalization
 */
export function normalizeStatus(status) {
  if (typeof status !== 'string') {
    return status;
  }
  return status.toLowerCase().replace(/_/g, '-');
}

/**
 * Get state display info
 */
export function getStateDisplayInfo(state) {
  const stateInfo = {
    [ReservationState.DRAFT]: { label: 'Draft', color: 'yellow', description: 'Request not yet confirmed' },
    [ReservationState.CONFIRMED]: { label: 'Confirmed', color: 'blue', description: 'Ready for checkout' },
    [ReservationState['CHECKED-OUT']]: { label: 'Checked Out', color: 'orange', description: 'Equipment on loan' },
    [ReservationState.RETURNED]: { label: 'Returned', color: 'green', description: 'Checkout completed' },
    [ReservationState.CANCELLED]: { label: 'Cancelled', color: 'red', description: 'Reservation cancelled' },
    [ReservationState.EXPIRED]: { label: 'Expired', color: 'gray', description: 'Deadline passed' },
  };
  return stateInfo[state] || { label: state, color: 'gray', description: 'Unknown state' };
}

/**
 * Table-driven tests for Reservation State Machine
 * Tests all state transitions, validation rules, and conflict detection
 */

import { describe, test, expect } from 'node:test';
import assert from 'node:assert';
import {
  createReservation,
  confirmReservation,
  checkoutReservation,
  completeCheckout,
  returnReservation,
  finalizeReturn,
  cancelReservation,
  expireReservation,
  ReservationState,
  getValidTransitions,
  isValidTransition,
  cloneInterval,
  intervalsOverlap,
} from '../src/reservationStateMachine.js';

describe('Reservation State Machine - State Transitions', () => {
  test('valid transitions from DRAFT state', () => {
    const transitions = getValidTransitions(ReservationState.DRAFT);
    expect(transitions).toContain(ReservationState.CONFIRMED);
    expect(transitions).toContain(ReservationState.CANCELLED);
    expect(transitions.length).toBe(2);
  });

