describe('Confirmation Rules - Non-Conflicting Interval Endpoints', () => {
  const now = new Date();
  const oneHourLater = new Date(now.getTime() + 3600000);
  const twoHoursLater = new Date(now.getTime() + 7200000);

  const equipment = {
    id: 'eq_001',
    name: 'Power Drill',
    maintenance: { state: 'ok' },
    status: 'available',
  };

  const reservation = createReservation({
    equipmentId: 'eq_001',
    borrowerId: 'user_001',
    requestedAt: now,
    interval: { start: oneHourLater, end: twoHoursLater },
    autoRenew: false,
  });

  // Test case where a reservation starts at the exact same time another ends (abut)
  const existingReservation = {
    id: 'res_002',
    equipmentId: 'eq_001',
    borrowerId: 'user_002',
    interval: { start: oneHourLater, end: twoHoursLater },
    status: ReservationState.CONFIRMED,
    requestedAt: new Date(now.getTime() - 1000),
  };

  const result = confirmReservation(reservation, equipment, [existingReservation], () => true);

  // A half-open interval [a, b) does NOT overlap [a', b') when a == b (start == end).
  // Example: interval [1h, 2h) with start=2h, end=3h: 2h < 3h AND 1h < 3h → true (overlap)
  // When start == b and end == b, start < end becomes 2h < 3h → true (strict)
  // But start == end of other means we have start < end (true), but we also have inner.start == a and inner.end == b
  // We need to check if there's any intersection. Since [1h, 2h) and [2h, 3h) do not intersect, intervalsOverlap should be false.
  const resultOverlap = intervalsOverlap(reservation.interval, existingReservation.interval);

  expect(resultOverlap).toBe(false);
});

