        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true, window.start, window.end).updated;
      const checkout = completeCheckout(confirmed, equipment, () => 'available');
      const final = completeCheckout(checkout.updated, checkout.updated, () => 'in_use');
      const ret = completeCheckout(final.updated, final.updated, () => 'available');

      expect(checkout.allowed).toBe(true);
      expect(checkout.updated.status).toBe(ReservationState['CHECKED-OUT']);
      expect(ret.allowed).toBe(true);
      expect(ret.updated.status).toBe(ReservationState.RETURNED);
    });
  });

  describe('Multiple Equipment Overlap', () => {
    const now = new Date(Date.now() - 10000000);

    test('prevents overlapping reservations on same equipment and borrower', () => {
      const oneHour = 3600000;
      const twoHours = 7200000;
      const threeHours = 10800000;

      const equipment = {
        id: 'eq_001',
        name: 'Power Drill',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const res1 = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + oneHour), end: new Date(now.getTime() + twoHours) },
        autoRenew: false,
      });

      const res2 = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001', // Same borrower
        requestedAt: now,
        interval: { start: new Date(now.getTime() + something), end: new Date(now.getTime() + somethingElse) },
        autoRenew: false,
      });

      // Simpler test: check if overlap detection works
      const overlapResult = confirmReservation(res1, equipment, [res1], () => true);
      expect(overlapResult.allowed).toBe(true); // Confirmed no overlap yet

      // Add overlapping reservation
      const resOverlapping = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + oneHour), end: new Date(now.getTime() + twoHours) }, // Exact overlap
        autoRenew: false,
      });

      const overlapCheck = confirmReservation(resOverlapping, equipment, [res1], () => true);
      expect(overlapCheck.reason).toContain('overlapping');
    });
  });
});

