/**
 * Edge cases for Reservation State Machine
 * Tests boundary conditions, exact intervals, and complex scenarios
 */

import { describe, test, expect } from 'node:test';
import assert from 'node:assert';
import {
  createReservation,
  confirmReservation,
  checkoutReservation,
  completeCheckout,
  returnReservation,
  finalizeReturn,
  cancelReservation,
  expireReservation,
  ReservationState,
  getStateDisplayInfo,
  ReservationState as Rs,
} from '../src/reservationStateMachine.js';

describe('Reservation State Machine - Edge Cases', () => {
  describe('Exact Interval Endpoints', () => {
    const now = new Date(Date.now() - 10000000);

    test('interval starting exactly when another ends (right after)', () => {
      const oneHour = 3600000;
      const equipment = {
        id: 'eq_001',
        name: 'Power Drill',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      // Reservation A: [now+1h, now+2h)
      const resA = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + oneHour), end: new Date(now.getTime() + oneHour * 2) },
        autoRenew: false,
      });

      // Reservation B: [now+2h, now+3h) - starts when A ends
      const resB = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_002',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + oneHour * 2), end: new Date(now.getTime() + oneHour * 3) },
        autoRenew: false,
      });

      const resultA = confirmReservation(resA, equipment, [], () => true);
      const resultB = confirmReservation(resB, equipment, [resA], () => true);

      expect(resultA.allowed).toBe(true);
      expect(resultB.allowed).toBe(true);
    });

    test('zero-length interval (start == end)', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const res = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 1000), end: new Date(now.getTime() + 1000) },
        autoRenew: false,
      });

      const result = confirmReservation(res, equipment, [], () => true);

      expect(result.allowed).toBe(true);
    });

    test('interval starting before current window', () => {
      const now = new Date(Date.now() - 10000000);
      const windowStart = new Date(Date.now() + 72 * 60 * 1000); // now + 2h
      const windowEnd = new Date(Date.now() + 33 * 60 * 60 * 1000); // 33h window

      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const res = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 1000), end: new Date(now.getTime() + 40 * 60 * 1000) },
        autoRenew: false,
      });

      const result = confirmReservation(res, equipment, [], () => true, windowStart, windowEnd);

      // Start is before window, should fail
      expect(result.reason).toContain('start time is before current interval start');
    });

    test('interval ending before current window', () => {
      const now = new Date(Date.now() - 10000000);
      const windowStart = new Date(Date.now() + 100 * 60 * 1000);
      const windowEnd = new Date(Date.now() + 72 * 60 * 1000);

      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const res = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(Date.now() + 100 * 60 * 1000), end: new Date(Date.now() + 50 * 60 * 1000) },
        autoRenew: false,
      });

      const result = confirmReservation(res, equipment, [], () => true, windowStart, windowEnd);

      // End is before window, should fail
      expect(result.reason).toContain('end time is before current interval start');
    });
  });

  describe('Checkout and Return Constraints', () => {
    const now = new Date(Date.now() - 10000000);
    const equipment = {
      id: 'eq_001',
      name: 'Power Drill',
      maintenance: { state: 'ok' },
      status: 'available',
    };

    test('cannot return equipment not in use', () => {
      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const result = returnReservation(confirmed, equipment, () => 'available');

      expect(result.allowed).toBe(false);
      expect(result.reason).toContain('Cannot return from state');
    });

    test('cannot complete checkout twice', () => {
      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const checkout1 = completeCheckout(confirmed, equipment, () => 'available');
      const equipmentStatus = () => 'in_use';
      const checkout2 = completeCheckout(checkout1.updated, checkout1.updated, equipmentStatus);

      expect(checkout2.reason).toContain('Checkout already started');
    });

    test('cannot finalize return no checkout session', () => {
      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const result = finalizeReturn(confirmed, equipment, () => 'available');

      expect(result.reason).toContain('No checkout session found');
    });

    test('cannot finalize return from wrong state', () => {
      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Try to finalize from confirmed state
      const result = finalizeReturn(confirmed, equipment, () => 'available');

      expect(result.reason).toContain('Cannot finalize return from state');
    });

    test('40-minute buffer for checkout', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Power Drill',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: new Date(Date.now() - 10000000),
        interval: { start: new Date(Date.now() - 20000000), end: new Date(Date.now() - 20000000 + 3600000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Simulate 31 minutes after confirmed time ( exceeds 30m buffer )
      const checkoutTime = new Date(confirmed.confirmedAt.getTime() + 31 * 60 * 1000);

      const result = checkoutReservation(confirmed, equipment, () => 'available');

      expect(result.reason).toContain('Reservation checkout time exceeded 30-minute buffer');
    });

    test('within 30-minute buffer', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Power Drill',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Simulate 25 minutes after confirmed time
      const checkoutTime = new Date(confirmed.confirmedAt.getTime() + 25 * 60 * 1000);

      const result = checkoutReservation(confirmed, equipment, () => 'available');

      expect(result.allowed).toBe(true);
    });
  });

  describe('Cancellation Rules', () => {
    const now = new Date(Date.now() - 10000000);

    test('cancel within 48-hour grace period by original borrower', () => {
      const deadline = new Date(Date.now() + 86400000); // 24h in future

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      // Simulate confirming
      const confirmed = confirmReservation(draft, { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' }, [], () => true).updated;

      // Cancel within grace period (requestedAt + 48h >= now)
      const graceTime = new Date(confirmed.requestedAt.getTime() + 36 * 60 * 60 * 1000); // 36h
      const result = cancelReservation(confirmed, graceTime, 'Test cancellation', 'user_001');

      expect(result.allowed).toBe(true);
    });

    test('cancel outside grace period requires coordinator', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Cancel 36h after (outside grace period of 48h)
      // logic: graceDeadline = Math.max(requestedTime, confirmedTime + 48h). If requested > confirmed, use requested.
      const cancellationDeadline = new Date(confirmed.confirmedAt.getTime() + 36 * 60 * 60 * 1000); // 36h after confirmed
      const result = cancelReservation(confirmed, cancellationDeadline, 'Test', 'user_001'); // same borrower, no coordinator

      expect(result.reason).toContain('only equipment coordinator can cancel');
    });

    test('cancel from checked-out state is allowed', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const checked = completeCheckout(confirmed, equipment, () => 'available').updated;
      const result = cancelReservation(checked, Infinity, 'Test', null);

      // checked-out is cancelable
      expect(isValidTransition(ReservationState['CHECKED-OUT'], ReservationState.CANCELLED)).toBe(true);
      expect(result.allowed).toBe(true);
    });

    test('cancel from returned state is not allowed', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const checked = completeCheckout(confirmed, equipment, () => 'available').updated;
      const returned = completeCheckout(checked, checked, () => 'available').updated;

      const result = cancelReservation(returned, Infinity, 'Test', null);

      expect(isValidTransition(ReservationState.RETURNED, ReservationState.CANCELLED)).toBe(false);
      expect(result.allowed).toBe(false);
    });
  });

  describe('Expiration Rules', () => {
    const now = new Date(Date.now() - 10000000);

    test('cannot expire from checked-out state', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Try to expire after checkout
      const checked = completeCheckout(confirmed, equipment, () => 'available').updated;
      const expirResult = expireReservation(checked, new Date(Date.now() + 24 * 60 * 60 * 1000));

      expect(expirResult.reason).toContain('Cannot expire checked-out reservation');
    });

    test('cannot expire from returned state', () => {
      const now = new Date(Date.now() - 10000000);
      const equipment = {
        id: 'eq_001',
        name: 'Tool',
        maintenance: { state: 'ok' },
        status: 'available',
      };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: now,
        interval: { start: new Date(now.getTime() + 3600000), end: new Date(now.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      const returned = completeCheckout(confirmed, equipment, () => 'available').updated;

      const expirResult = expireReservation(returned, new Date(Date.now() + 24 * 60 * 60 * 1000));

      expect(expirResult.reason).toContain('Cannot expire from state');
    });

    test('expire at deadline', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Set expiration before now (or now + 24h)
      const expiration = new Date(nowDate.getTime() + 86400000); // 1 day in future
      const result = expireReservation(confirmed, expiration);

      expect(result.allowed).toBe(true);
      expect(result.updated.status).toBe(ReservationState.EXPIRED);
    });

    test('expire not yet time', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      const draft = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const confirmed = confirmReservation(draft, equipment, [], () => true).updated;

      // Expiration is 2 hours in future
      const expiration = new Date(nowDate.getTime() + 3600000);

      const result = expireReservation(confirmed, expiration);

      expect(result.reason).toContain('not yet expired');
    });
  });

  describe('Multiple Overlap Scenarios', () => {
    const now = new Date(Date.now() - 10000000);

    test('three overlapping reservations on same equipment', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      const res1 = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 10800000) },
        autoRenew: false,
      });

      const res2 = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_002',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 5400000), end: new Date(nowDate.getTime() + 14400000) },
        autoRenew: false,
      });

      const res3 = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_003',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 7200000), end: new Date(nowDate.getTime() + 18000000) },
        autoRenew: false,
      });

      const result1 = confirmReservation(res1, equipment, [], () => true);
      const result2 = confirmReservation(res2, equipment, [res1], () => true);
      const result3 = confirmReservation(res3, equipment, [res1, res2], () => true);

      expect(result1.allowed).toBe(true);
      expect(result2.allowed).toBe(true);
      expect(result3.allowed).toBe(true);
    });

    test('reservation that encloses another', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const equipment = { id: 'eq_001', name: 'Tool', maintenance: { state: 'ok' }, status: 'available' };

      // Outer reservation
      const outer = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 10080000) },
        autoRenew: false,
      });

      // Inner reservation (outside of it)
      const inner = createReservation({
        equipmentId: 'eq_001',
        borrowerId: 'user_002',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 7200000), end: new Date(nowDate.getTime() + 8640000) },
        autoRenew: false,
      });

      // Overlaps anyway
      const outerConf = confirmReservation(outer, equipment, [], () => true);
      const innerConf = confirmReservation(inner, equipment, [outer], () => true);

      expect(innerConf.allowed).toBe(true);
    });
  });

  describe('Status Display Info', () => {
    test('returns display info for all states', () => {
      const states = [
        ReservationState.DRAFT,
        ReservationState.CONFIRMED,
        ReservationState['CHECKED-OUT'],
        ReservationState.RETURNED,
        ReservationState.CANCELLED,
        ReservationState.EXPIRED,
      ];

      states.forEach((state) => {
        const info = getStateDisplayInfo(state);
        expect(info.label).toBeTruthy();
        expect(info.color).toBeTruthy();
        expect(info.description).toBeTruthy();
      });
    });

    test('returns default info for unknown state', () => {
      const info = getStateDisplayInfo('unknown_state');
      expect(info.label).toBe('unknown_state');
      expect(info.color).toBe('gray');
      expect(info.description).toBe('Unknown state');
    });
  });

  describe('Concurrency Scenarios', () => {
    const now = new Date(Date.now() - 10000000);

    test('can create multiple concurrent reservations with different equipment', () => {
      const nowDate = new Date(Date.now() - 10000000);
      const statusAvailable = () => 'available';

      const drill = createReservation({
        equipmentId: 'eq_drill',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const saw = createReservation({
        equipmentId: 'eq_saw',
        borrowerId: 'user_002',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
        autoRenew: false,
      });

      const welder = createReservation({
        equipmentId: 'eq_welder',
        borrowerId: 'user_001',
        requestedAt: nowDate,
        interval: { start: new Date(nowDate.getTime() + 3600000), end: new Date(nowDate.getTime() + 7200000) },
