      expect(getValidTransitions(ReservationState.DRAFT)).toContain(ReservationState.CONFIRMED);
      expect(getValidTransitions(ReservationState.DRAFT)).toContain(ReservationState.CANCELLED);

      // All valid paths from confirmed
      expect(getValidTransitions(ReservationState.CONFIRMED)).toContain(ReservationState.CHECKED-OUT);
