      expect(getValidTransitions(ReservationState['CHECKED-OUT'])).toContain(ReservationState.RETURNED);
      expect(getValidTransitions(ReservationState['CHECKED-OUT'])).toContain(ReservationState.CANCELLED);

      // Terminal states
      expect(getValidTransitions(ReservationState.RETURNED)).toEqual([]);
      expect(getValidTransitions(ReservationState.CANCELLED)).toEqual([]);
      expect(getValidTransitions(ReservationState.EXPIRED)).toEqual([]);
    });
